def expand_to_rectangle(left: int, top: int, size: int) -> List[int]:
    """Expand a list of M&Ms filled to the border of the rectangle,
    and resize the remaining borders to the updated size."""
    re: List[int] = []
    to_fill_up_border: List[int] = []
    for i in range(len(m)):
        color = m[i]
        if i > left:
            to_fill_up_border.append(color)
        re.append(color)
        if i == size + left - 1:
            to_fill_up_border.append(color)
            break
    for i in range(len(m), size + top):
        re.append(m[i - size])
    if to_fill_up_border:
        re = re + to_fill_up_border
    return re

def count_colorful_mms(left: int, top: int, size: int) -> int:
