from collections import defaultdict, deque

def shortest_path(G, s, t):
    queue = deque([(s, 0)])
    visited = defaultdict(lambda: -1)
    visited[s] = 0

    while queue:
        u, dist = queue.popleft()
        if u != t:
            for v, weight in G[u]:
                if visited[v] == -1 and dist + 1 < weight:
                    queue.append((v, dist + 1))
                    visited[v] = dist + 1

    return visited[t]

def bfs(G, s, t):
    visited = defaultdict(lambda: -1)
    queue = deque([(s, [])])
    visited[s] = 0

    while queue:
        u, path = queue.popleft()
        for v, weight in G[u]:
            if visited[v] == -1 and shortest_path(G, u, v) == weight:
                path.append(v)
                if v == t:
                    return path
                queue.append((v, path))
                visited[v] = shortest_path(G, u, v) + 1

def find_shortest_path(G, s, t):
    shortest_path = shortest_path(G, s, t)
    return bfs(G, s, t) + shortest_path

