import math

def get_permutaution(nums):
    n = len(nums)
    permutation = [0] * n
    for i in range(n):
        permutation[i] = nums[(i + nums[i]) % n]
    return permutation

def count_colorfulness(permutation, k):
    colorfulness = 0
    for i in range(len(permutation)):
        for j in range(i + 1, len(permutation)):
            if len((permutation[i], permutation[j])) == k:
                colorfulness += 1
    return colorfulness

def expected_colorfulness(n, k, blocks):
    colors = [0] * n
    for i, (A, C) in enumerate(blocks):
        colors[C] += A
    total = sum(colors)
    expected = 0
    for i in range(total):
        prob = 1 / math.factorial(n)
        prod = 1
        for j in range(n):
            if colors[j] > i:
                prod *= (colors[j] - i) / i
            elif colors[j] == i:
                prod *= (colors[j] - i) / (i * (n - j))
        expected -= prob * prod
    expected = expected * (n * (n + 1) / 2)
    return expected

def solution(T, blocks):
    answer = []
    for _ in range(T):
        n, k = map(int, input().split())
        permutation = get_permutaution(list(range(n)))
        result = count_colorfulness(permutation, k // 2)
        expected = expected_colorfulness(n, k, blocks)
        answer.append(expected / result)
    return answer

# Example usage:
T = 1
blocks = [
    [3, 1], [2, 2], [2, 1], [4, 3], [1, 2], [1, 3], [4, 4]
]
solution(T, blocks)
