def calculate_colorfulness(n, k, blocks):
    def dfs(block, index):
        if index == len(blocks):
            return 1
        if blocks[index] == block:
            return 0
        has_same_color = 0
        for j in range(index, len(blocks)):
            if dfs(blocks[j], j):
                has_same_color = 1
                break
        return has_same_color

    color_fullness = 0
    for block in range(n):
        has_same_color = dfs(block, 0)
        if has_same_color:
            color_fullness += n - block
    for block in range(n):
        for other_block in range(n):
            if other_block != block:
                has_same_color = dfs(other_block, 0)
                if has_same_color:
                    color_fullness += 1
    for block in range(n):
        for other_block in range(n):
            if other_block != block:
                for final_block in range(n):
                    if final_block != block and final_block != other_block:
                        has_same_color = dfs(final_block, 0)
                        if has_same_color:
                            color_fullness += 1
    return n ** 2 - 3 * n + 2 * (k + 1 - n ** 2 + 2 * n)

