class MutableBit:
    def __init__(self, n):
        self.n = n
        self.x = [0] * (n + 1)

    def lowbit(self, x):
        return x & (-x)

    def add(self, x, val):
        while x <= self.n:
            self.x[x] += val
            x += self.lowbit(x)

    def get(self, x):
        rt = 0
        while x >= 1:
            rt += self.x[x]
            x -= self.lowbit(x)
        return rt

