def seconds_to_time(seconds):
    hours = seconds // 3600
    minutes = (seconds % 3600) // 60
    return (hours, minutes)

def time_diff(time1, time2):
    hours1, minutes1 = time1
    hours2, minutes2 = time2
    if hours1 > hours2:
        hours1, hours2 = hours2, hours1
    if minutes1 > minutes2:
        minutes1, minutes2 = minutes2, minutes1
    return (hours1 * 100 + minutes1 - (hours2 * 100 + minutes2), -24)

def counting_changes(h, m, k, h1, m1, h2, m2):
    total_changes = 0
    for i in range(24 * 60):
        seconds = h1 + i // 60 + (i % 60) * h1 // 60
        current_time = seconds_to_time(seconds)
        for j in range(24 * 60):
            seconds = h2 + j // 60 + (j % 60) * h2 // 60
            next_time = seconds_to_time(seconds)
            if time_diff(current_time, next_time)[0] >= k:
                total_changes += 1
            current_time = next_time
    return total_changes

