def count_awesome_substrings(binary_string):
    def is_divisible_by_ones(length, ones):
        return length % ones == 0

    def maximize_or_with_ones(index, lazy_or_index, ones_count):
        nonlocal max_len
        if is_divisible_by_ones(length_binary_string, ones_count):
            if max_len < length_binary_string[index:]:
                max_len = length_binary_string[index:]
                max_len_index = index
            return True
        while index < lazy_or_index:
            if length_binary_string[index] == '0':
                break
            index += 1
            if is_divisible_by_ones(index - lazy_or_index, ones_count):
                if max_len < length_binary_string[index:]:
                    max_len = length_binary_string[index:]
                    max_len_index = index
                return
            while index < lazy_or_index:
                if length_binary_string[index] == '0':
                    break
                index += 1

    max_len = ""
    max_len_index = 0
    for i in range(len(binary_string)):
        lazy_or_index = i + 1
        length_binary_string = binary_string[i:]
        maximize_or_with_ones(i, lazy_or_index, 1)
        maximize_or_with_ones(i, lazy_or_index, 0)
        if length_binary_string[0] == '1':
            maximize_or_with_ones(i, lazy_or_index, 1)
        if length_binary_string[0] == '0':
            maximize_or_with_ones(i, lazy_or_index, 0)

    print(len(max_len))
    return

