            DP[y][1] %= mod

    ans = 0
    for c in range(1, k+1):
        ans += (DP[L][c] - DP[L-1][c]) * (L - (L - inc_y))
        ans %= mod
    for x in range(1, L+1):
        ans += (DP[x][k] - DP[x-1][k]) * (2*min(L - x, inc_y) - 1)
        ans %= mod
    for x in range(1, L+1):
        ans += (DP[x-1][k-1] - DP[x-2][k-1]) * ((L - x) * (L - x - 1) // 2)
        ans %= mod

    for x in range(1, L+1):
        for y in range(1, L+1):
            if x >= inc_y or y >= inc_y:
                ans -= (DP[x][y] - DP[x-1][y]) * (2*min(L-x, inc_y) - 1)
    for x in range(1, L+1):
        for y in range(inc_y, L+1):
            ans -= (DP[x][y] - DP[x-1][y]) * (2*(L-x) - 1)
    for x, y in [(L-inc_y, L-inc_y)]*(inc_y*L-1) + [(L-inc_y, 1)-(1,inc_y)]*(inc_y*L-2):
        ans -= (DP[x][y] - DP[x-1][y]) * (2*min(inc_y*(L-1)-x, inc_y) - 1)
