import heapq

def dijkstra(graph, start, end, k):
    n = len(graph)
    distances = {i: float('inf') for i in range(1, n + 1)}
    distances[start] = 0
    queue = [(0, start)]

    while queue:
        current_distance, current_node = heapq.heappop(queue)

        if current_distance > distances[current_node] or current_distance > k:
            continue

        if current_node == end:
            return current_distance

        for neighbor in graph[current_node]:
            distance = current_distance + 1  # Shortcutting path
            if distance <= k and distance + start_to_neighbor < distances[neighbor]:
                distances[neighbor] = distance + start_to_neighbor
                heapq.heappush(queue, (distance + start_to_neighbor, neighbor))

    return -1  # No valid path found

def add_shortcuts(graph, k, shortcuts_added):
    num_shortcuts = 0
    processed_nodes = set()
    queue = [(start, 0) for start in range(1, n + 1)]

    while queue:
        current_node, current_distance = queue.pop(0)

        if current_node in processed_nodes or current_distance > k:
            continue

        if current_node == end:
            num_shortcuts += n - len(processed_nodes)
            return num_shortcuts + shortcuts_added

        e = dijkstra(graph, start, end, k)
        if e != -1:
            num_shortcuts += 1
            shortcuts_added += 1
            for i in range(1, n + 1):
                if i not in processed_nodes and graph[i] and distances[i] + 1 < distances[start] and distances[i] < distances[e]:
                    graph[i] = []
            break

        processed_nodes.add(current_node)
        for neighbor in graph[current_node]:
            queue.append((neighbor, current_distance + 1))

    return num_shortcuts

