def min_switches(off_bulbs):
    min_switches = 0
    for bulbs in off_bulbs:
        seen = set()
        need = set(bulbs)
        current = 0
        for bulb in bulbs:
            seen.add(bulb)
            current ^= bulb
        while need:
            in_seeds = 0
            off = need.pop()
